// Verificación de la firma de BUROINSTANT.
//
// La firma se calcula sobre los BYTES EXACTOS que llegaron, no sobre el JSON
// re-serializado: volver a serializar puede cambiar el orden de las claves o el
// escapado y romper una firma que era buena.
//
// Se comprueban tres cosas y las tres tienen que pasar:
//   1. Que el secreto esté configurado. Sin secreto no se acepta nada.
//   2. Que la marca de tiempo tenga menos de 5 minutos, para que nadie pueda
//      reenviar una petición legítima capturada antes.
//   3. Que la firma coincida, comparada en tiempo constante.

const crypto = require('crypto');

const MAX_SKEW_MS = 5 * 60 * 1000;

// FALLA CERRADO. Algunas instalaciones de n8n ejecutan los nodos Code en un
// runner que bloquea el acceso al entorno: leerlo lanza. Se envuelve, y si no
// se puede leer el secreto se rechaza diciendo exactamente que falta
// configurar. Un fallo que deja pasar es peor que un fallo que corta.
function rechazar(motivo) {
  return { json: { valido: false, motivo, phone: null, text: null, idempotencyKey: null } };
}

let SECRET = '';
try {
  SECRET = $env.BUROINSTANT_OUTBOUND_SECRET || '';
} catch (error) {
  return rechazar('ENV_ACCESS_DENIED');
}

const headers = $input.item.json.headers || {};
const timestamp = headers['x-buroinstant-timestamp'] || '';
const signatureHeader = String(headers['x-buroinstant-signature'] || '');
const signature = signatureHeader.replace(/^sha256=/, '');

// Cuerpo crudo. Con rawBody activado, n8n lo deja en binario base64.
let rawBody = '';
const binary = $input.item.binary;
if (binary && binary.data && binary.data.data) {
  rawBody = Buffer.from(binary.data.data, 'base64').toString('utf8');
} else if (typeof $input.item.json.rawBody === 'string') {
  rawBody = $input.item.json.rawBody;
} else {
  rawBody = JSON.stringify($input.item.json.body || {});
}

function rechazar(motivo) {
  return { json: { valido: false, motivo, phone: null, text: null, idempotencyKey: null } };
}

if (!SECRET || SECRET.length < 24) return rechazar('SECRET_NOT_CONFIGURED');
if (!timestamp || !signature) return rechazar('MISSING_SIGNATURE');

const ts = Date.parse(timestamp);
if (!Number.isFinite(ts)) return rechazar('BAD_TIMESTAMP');
if (Math.abs(Date.now() - ts) > MAX_SKEW_MS) return rechazar('TIMESTAMP_OUT_OF_WINDOW');

const esperado = crypto.createHmac('sha256', SECRET).update(timestamp + '.' + rawBody).digest('hex');
const a = Buffer.from(esperado, 'utf8');
const b = Buffer.from(signature, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return rechazar('BAD_SIGNATURE');

// Sólo a partir de aquí se mira el contenido: antes de verificar la firma, el
// cuerpo es de origen desconocido.
let cuerpo;
try {
  cuerpo = JSON.parse(rawBody);
} catch (error) {
  return rechazar('BODY_NOT_JSON');
}

const phone = String(cuerpo.phone || '').replace(/\D/g, '');
const text = String(cuerpo.text || '');
if (!/^[0-9]{7,20}$/.test(phone)) return rechazar('BAD_PHONE');
if (text.length < 1 || text.length > 4000) return rechazar('BAD_TEXT');
if (cuerpo.source !== 'BUROINSTANT_DEADLINE_REMINDER') return rechazar('BAD_SOURCE');

return {
  json: {
    valido: true,
    motivo: 'OK',
    phone,
    text,
    idempotencyKey: String(cuerpo.idempotencyKey || ''),
  },
};
